import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from specs5 import *

# Second pass of the everyday cases: levels that raise the ceiling of modes that had no hard level,
# and a horse level that replaces the sweet-corn one (too close to `inh-corn`).

inh_palomino = inh_spec('inh-palomino', B('Palomino horses', 'Caballos palominos'), B('Two copies, three colours', 'Dos copias, tres colores'), 'intermediate', 6, 'cell',
    B('Fill in the Punnett squares for horse colour: one cream allele dilutes the coat and two dilute it much more.', 'Rellena los cuadros de Punnett del color de los caballos: un alelo crema diluye el pelaje y dos lo diluyen mucho más.'),
    B('A palomino horse has a golden coat and a pale mane. Breeders know that two palominos do not always have palomino foals, and the squares tell why.', 'Un caballo palomino tiene el pelaje dorado y las crines claras. Quien cría caballos sabe que dos palominos no siempre tienen potros palominos, y los cuadros explican por qué.'),
    org('horse-palomino', 'Horse', 'Caballo', 'Equus caballus', B('A domestic animal with many coat colours.', 'Un animal doméstico con muchos colores de pelaje.'), MAMMAL + ['Perissodactyla', 'Equidae', 'Equus'], tissue='skin'),
    [ex('cell', B('Three colours', 'Tres colores'), B('Chestnut, palomino, cremello', 'Alazán, palomino y cremello'), B('A chestnut horse is reddish brown. One copy of the cream allele turns it into a golden palomino, and two copies turn it into a very pale cremello.', 'Un caballo alazán es marrón rojizo. Una copia del alelo crema lo convierte en un palomino dorado, y dos copias lo convierten en un cremello muy claro.')),
     ex('dna', B('Incomplete dominance', 'Dominancia incompleta'), B('The middle colour is a mix', 'El color del medio es una mezcla'), B('Neither allele hides the other: the animal with one copy of each shows an in-between colour, as in the pink snapdragons.', 'Ningún alelo oculta al otro: el animal con una copia de cada uno muestra un color intermedio, como los dragones de color rosa.'))],
    dict(trait=B('Coat colour', 'Color del pelaje'), alleles=['N', 'R'], phenotypes={'NN': 'chestnut', 'NR': 'palomino', 'RR': 'cremello'},
         labels={'chestnut': B('Chestnut', 'Alazán'), 'palomino': B('Palomino', 'Palomino'), 'cremello': B('Cremello', 'Cremello')},
         scenarios=[
             sc('NR', 'NR', B('Palomino', 'Palomino'), B('Palomino', 'Palomino'), B('Two palomino horses (NR) have a foal. What is the probability that the foal is palomino like them?', 'Dos caballos palominos (NR) tienen un potro. ¿Qué probabilidad hay de que el potro sea palomino como ellos?'), 'palomino',
                B('Two cells are NR: 50%. The others are NN (chestnut) and RR (cremello), 25% each.', 'Dos casillas son NR: 50 %. Las otras son NN (alazán) y RR (cremello), 25 % cada una.')),
             sc('NN', 'RR', B('Chestnut', 'Alazán'), B('Cremello', 'Cremello'), B('A chestnut horse (NN) and a cremello (RR) have a foal. What is the probability that the foal is palomino?', 'Un caballo alazán (NN) y un cremello (RR) tienen un potro. ¿Qué probabilidad hay de que el potro sea palomino?'), 'palomino',
                B('All four cells are NR: every foal is palomino (100%). This is the usual way to breed palominos.', 'Las cuatro casillas son NR: todos los potros son palominos (100 %). Es la forma habitual de criar palominos.')),
             sc('NR', 'NN', B('Palomino', 'Palomino'), B('Chestnut', 'Alazán'), B('A palomino (NR) and a chestnut horse (NN) have a foal. What is the probability that the foal is chestnut?', 'Un palomino (NR) y un caballo alazán (NN) tienen un potro. ¿Qué probabilidad hay de que el potro sea alazán?'), 'chestnut',
                B('Two cells are NN (chestnut) and two are NR (palomino): 50% each.', 'Dos casillas son NN (alazán) y dos son NR (palomino): 50 % cada una.'))]),
    [B('Fill the square first; then read each cell. Here every genotype has its own colour.', 'Rellena primero el cuadro; luego lee cada casilla. Aquí cada genotipo tiene su propio color.'),
     B('NN is chestnut, NR is palomino and RR is cremello.', 'NN es alazán, NR es palomino y RR es cremello.'),
     B('Count the cells of the colour asked about: each is worth 25%.', 'Cuenta las casillas del color por el que preguntan: cada una vale un 25 %.')],
    **closing(B('A colour in the middle', 'Un color en el medio'),
              B('You saw that when neither allele is dominant, the middle genotype has its own colour and two palominos can have foals of three colours.', 'Has visto que cuando ningún alelo es dominante el genotipo intermedio tiene su propio color y que dos palominos pueden tener potros de tres colores.'),
              B('Horse breeders choose the parents with these squares, because crossing a chestnut with a cremello gives palomino foals every time.', 'Quien cría caballos elige los padres con estos cuadros, porque cruzar un alazán con un cremello da potros palominos siempre.'),
              B('In 2003 a team showed that the cream coat colour of horses comes from a change in a gene called MATP, which also takes part in pigment cells of other animals.', 'En 2003 un equipo mostró que el color crema del pelaje de los caballos viene de un cambio en un gen llamado MATP, que también interviene en las células del pigmento de otros animales.'),
              B('A single change in the MATP gene makes a transporter of pigment cells work less. One copy dilutes the red colour into gold; two copies dilute it almost completely.', 'Un único cambio en el gen MATP hace que un transportador de las células del pigmento trabaje menos. Una copia diluye el rojo hasta el dorado; dos copias lo diluyen casi por completo.'),
              [B('Horse colours depend on many genes; here only the cream gene is followed, on a chestnut background.', 'Los colores de los caballos dependen de muchos genes; aquí solo se sigue el gen crema, sobre un fondo alazán.')],
              [ref(['Mariat, D.', 'Taourit, S.', 'Guérin, G.'], 2003, 'A mutation in the MATP gene causes the cream coat colour in the horse', 'Genetics Selection Evolution', '10.1186/1297-9686-35-1-119')]))

inh_rabbit = inh_spec('inh-rabbit', B('Three coats in one rabbit gene', 'Tres pelajes en un gen de conejo'), B('A ladder of dominance: C, h, c', 'Una escalera de dominancia: C, h, c'), 'advanced', 8, 'cell',
    B('Fill in the Punnett squares for rabbit colour, where three alleles form a ladder: C hides h, and h hides c.', 'Rellena los cuadros de Punnett del color de los conejos, donde tres alelos forman una escalera: C oculta a h, y h oculta a c.'),
    B('One gene of rabbits has several alleles. The full-colour one, C, makes a working enzyme; h makes a heat-shy enzyme that gives the Himalayan pattern; c makes none, so the rabbit is albino.', 'Un gen de los conejos tiene varios alelos. El de color completo, C, fabrica una enzima que funciona; h fabrica una enzima sensible al calor que da el patrón himalayo; c no fabrica ninguna, así que el conejo es albino.'),
    org('rabbit-coat', 'Rabbit', 'Conejo', 'Oryctolagus cuniculus', B('A domestic animal with several coat patterns.', 'Un animal doméstico con varios patrones de pelaje.'), MAMMAL + ['Lagomorpha', 'Leporidae', 'Oryctolagus'], tissue='skin'),
    [ex('cell', B('Three coats', 'Tres pelajes'), B('Full colour, Himalayan, albino', 'Color completo, himalayo y albino'), B('A Himalayan rabbit is white with dark ears, nose, feet and tail, like a Siamese cat. An albino rabbit is white all over, with pink eyes.', 'Un conejo himalayo es blanco con las orejas, el hocico, las patas y la cola oscuras, como un gato siamés. Un conejo albino es blanco por completo y tiene los ojos rosados.')),
     ex('dna', B('A ladder', 'Una escalera'), B('More than two alleles', 'Más de dos alelos'), B('A rabbit has only two alleles, but the population has three. The order of dominance decides what each pair shows.', 'Un conejo solo tiene dos alelos, pero la población tiene tres. El orden de dominancia decide lo que muestra cada pareja.'))],
    dict(trait=B('Coat', 'Pelaje'), alleles=['C', 'h', 'c'], phenotypes={'CC': 'full', 'Ch': 'full', 'Cc': 'full', 'hh': 'himalayan', 'hc': 'himalayan', 'cc': 'albino'},
         labels={'full': B('Full colour', 'Color completo'), 'himalayan': B('Himalayan', 'Himalayo'), 'albino': B('Albino', 'Albino')},
         scenarios=[
             sc('Ch', 'Cc', B('Full colour, carries h', 'Color completo, lleva h'), B('Full colour, carries c', 'Color completo, lleva c'), B('Two full-colour rabbits, one carrying h and the other carrying c, have kits. What is the probability of a Himalayan kit?', 'Dos conejos de color completo, uno que lleva h y otro que lleva c, tienen gazapos. ¿Qué probabilidad hay de un gazapo himalayo?'), 'himalayan',
                B('The four cells are CC, Cc, Ch and hc. Only hc is Himalayan: 25%.', 'Las cuatro casillas son CC, Cc, Ch y hc. Solo hc es himalaya: 25 %.')),
             sc('hc', 'hc', B('Himalayan, carries c', 'Himalayo, lleva c'), B('Himalayan, carries c', 'Himalayo, lleva c'), B('Two Himalayan rabbits that both carry c have kits. What is the probability of a Himalayan kit?', 'Dos conejos himalayos que llevan los dos c tienen gazapos. ¿Qué probabilidad hay de un gazapo himalayo?'), 'himalayan',
                B('The cells are hh, hc, hc and cc. Only cc is albino, so three of four are Himalayan: 75%.', 'Las casillas son hh, hc, hc y cc. Solo cc es albina, así que tres de cuatro son himalayas: 75 %.')),
             sc('Cc', 'hc', B('Full colour, carries c', 'Color completo, lleva c'), B('Himalayan, carries c', 'Himalayo, lleva c'), B('A full-colour rabbit that carries c and a Himalayan rabbit that carries c have kits. What is the probability of a full-colour kit?', 'Un conejo de color completo que lleva c y un conejo himalayo que lleva c tienen gazapos. ¿Qué probabilidad hay de un gazapo de color completo?'), 'full',
                B('The cells are Ch, Cc, hc and cc. The two with a C are full colour: 50%.', 'Las casillas son Ch, Cc, hc y cc. Las dos que llevan una C son de color completo: 50 %.'))]),
    [B('Work out the square first. Then ask yourself, for each cell: is there a C? If not, is there an h?', 'Resuelve primero el cuadro. Luego pregúntate, en cada casilla: ¿hay una C? Si no, ¿hay una h?'),
     B('A cell with C is full colour. A cell with h and no C is Himalayan. Only cc is albino.', 'Una casilla con C es de color completo. Una casilla con h y sin C es himalaya. Solo cc es albina.'),
     B('Count the cells of the coat asked about: each is worth 25%.', 'Cuenta las casillas del pelaje por el que preguntan: cada una vale un 25 %.')],
    **closing(B('A ladder of alleles', 'Una escalera de alelos'),
              B('You worked with three alleles at once and saw that a recessive allele can hide for generations before an albino kit appears.', 'Has trabajado con tres alelos a la vez y has visto que un alelo recesivo puede esconderse durante generaciones antes de que aparezca un gazapo albino.'),
              B('Series of alleles like this one are common: blood groups, coat colours and many plant traits follow the same logic.', 'Las series de alelos como esta son comunes: los grupos sanguíneos, los colores del pelaje y muchos rasgos de las plantas siguen la misma lógica.'),
              B('In 2000 a team studied the tyrosinase gene in different rabbit strains and showed that the albino and the Himalayan coats are linked to changes in that gene.', 'En 2000 un equipo estudió el gen de la tirosinasa en distintas razas de conejo y mostró que los pelajes albino e himalayo están relacionados con cambios en ese gen.'),
              B('The albino allele makes a tyrosinase with no activity, and the Himalayan allele a tyrosinase that works only at low temperatures, which is why the pigment appears in the cooler ears, nose, feet and tail.', 'El alelo albino fabrica una tirosinasa sin actividad, y el alelo himalayo una tirosinasa que solo funciona con temperaturas bajas, por eso el pigmento aparece en las orejas, el hocico, las patas y la cola, que están más frías.'),
              [B('Real rabbits have a fourth allele, the chinchilla one, between C and h; it is left out to keep the squares readable.', 'Los conejos reales tienen un cuarto alelo, el chinchilla, entre C y h; se omite para que los cuadros sean legibles.')],
              [ref(['Aigner, B.', 'Besenfelder, U.', 'Müller, M.', 'Brem, G.'], 2000, 'Tyrosinase gene variants in different rabbit strains', 'Mammalian Genome', '10.1007/s003350010120')]))

INSULIN_RNA = 'AUGUUUGUUAAUCAACAUCUUUGUGGUUCUCAUCUUGUUUAA'
RNA_AMINO = {'AUG': 'Met', 'UUU': 'Phe', 'GUU': 'Val', 'AAU': 'Asn', 'CAA': 'Gln', 'CAU': 'His', 'CUU': 'Leu', 'UGU': 'Cys', 'GGU': 'Gly', 'UCU': 'Ser', 'UAA': 'Stop'}
ins_en = ', '.join(RNA_AMINO[INSULIN_RNA[i:i + 3]] for i in range(0, len(INSULIN_RNA), 3))
ins_es = ins_en.replace('Stop', 'Fin')
pair_insulin = pair_spec('pair-insulin', B('The first words of insulin', 'Las primeras palabras de la insulina'), B('Thirteen codons and a stop', 'Trece codones y una parada'), 'advanced', 8, 'protein', INSULIN_RNA,
    B('Read the message that a bacterium would use to make the start of human insulin, and find the amino acid of each codon.', 'Lee el mensaje que usaría una bacteria para fabricar el comienzo de la insulina humana, y busca el aminoácido de cada codón.'),
    B('Read this messenger RNA three letters at a time and find the amino acid of each codon. It ends with a stop.', 'Lee este ARN mensajero de tres en tres letras y busca el aminoácido de cada codón. Acaba con una parada.'),
    [B('Split the message into groups of three and look each one up in the table. Keep the order.', 'Divide el mensaje en grupos de tres y busca cada uno en la tabla. Mantén el orden.'),
     B('The first codon is AUG (Met) and the last one is a stop. Between them there are eleven amino acids.', 'El primer codón es AUG (Met) y el último es de parada. Entre ellos hay once aminoácidos.'),
     B('The answers are: ' + ins_en + '.', 'Las respuestas son: ' + ins_es + '.')],
    [ex('bacterium', B('Insulin in bacteria', 'Insulina en bacterias'), B('A human gene, a bacterial reader', 'Un gen humano, un lector bacteriano'), B('Bacteria read the genetic code like us, so they can make human insulin once they receive its gene. The first amino acids of the chain B are Phe, Val, Asn, Gln, His, Leu, Cys, Gly, Ser, His, Leu and Val.', 'Las bacterias leen el código genético como nosotros, así que pueden fabricar insulina humana cuando reciben su gen. Los primeros aminoácidos de la cadena B son Phe, Val, Asn, Gln, His, Leu, Cys, Gly, Ser, His, Leu y Val.')),
     ex('dna', B('Start and stop', 'Inicio y parada'), B('Every message has both', 'Todo mensaje tiene las dos'), B('AUG tells the ribosome where to start and a stop codon tells it where to finish. In the bacterium, a Met is added at the start.', 'AUG dice al ribosoma dónde empezar y un codón de parada dónde terminar. En la bacteria se añade una Met al comienzo.'))],
    **closing(B('The start of a medicine', 'El comienzo de un medicamento'),
              B('You read a longer message, from the start signal to the stop, and found the amino acids that begin chain B of human insulin.', 'Has leído un mensaje más largo, de la señal de inicio a la parada, y has encontrado los aminoácidos con los que empieza la cadena B de la insulina humana.'),
              B('Human insulin made by bacteria has replaced the insulin that used to be taken from animals, and millions of people with diabetes use it every day.', 'La insulina humana fabricada por bacterias ha sustituido a la que antes se sacaba de animales, y millones de personas con diabetes la usan cada día.'),
              B('Insulin made in bacteria was the first medicine from genetic engineering to reach patients, in the early 1980s.', 'La insulina fabricada en bacterias fue el primer medicamento de ingeniería genética que llegó a los pacientes, a principios de los años ochenta.'),
              B('Chain B of insulin has 30 amino acids and starts with Phe-Val-Asn-Gln-His-Leu-Cys-Gly-Ser-His-Leu-Val. Each of them can be written with several codons; the message here is one possible choice.', 'La cadena B de la insulina tiene 30 aminoácidos y empieza con Phe-Val-Asn-Gln-His-Leu-Cys-Gly-Ser-His-Leu-Val. Cada uno puede escribirse con varios codones; el mensaje de aquí es una posible elección.'),
              [B('Only the first twelve amino acids are used, with a Met at the start and a stop at the end.', 'Solo se usan los doce primeros aminoácidos, con una Met al principio y una parada al final.')],
              []))

seq_swab = seq_spec('seq-swab', B('A DNA test for your cat', 'Un test de ADN para tu gato'), B('From a cheek swab to a genotype', 'De un frotis de la mejilla a un genotipo'), 'advanced', 8, 'dna',
    B('Put the steps of a simple DNA test in order: it uses PCR, a restriction enzyme and a gel to tell which alleles an animal carries.', 'Pon en orden los pasos de una prueba de ADN sencilla: usa PCR, una enzima de restricción y un gel para decir qué alelos lleva un animal.'),
    B('Is your cat a carrier of an allele that you cannot see? A laboratory can find out from a little saliva by combining several techniques you already know.', '¿Tu gato es portador de un alelo que no se ve? Un laboratorio puede averiguarlo con un poco de saliva combinando varias técnicas que ya conoces.'),
    org('cat-test', 'A cat and its DNA', 'Un gato y su ADN', 'Felis catus', B('A pet whose alleles are checked with a test.', 'Una mascota cuyos alelos se comprueban con una prueba.'), MAMMAL + ['Carnivora', 'Felidae', 'Felis'], tissue='cheek cells'),
    [ex('dna', B('The idea', 'La idea'), B('A changed letter changes a cut', 'Una letra cambiada cambia un corte'), B('If the changed letter creates or destroys the site of a restriction enzyme, the copies of one allele are cut and the copies of the other are not. The gel shows the difference.', 'Si la letra cambiada crea o destruye el sitio de una enzima de restricción, las copias de un alelo se cortan y las del otro no. El gel muestra la diferencia.')),
     ex('cell', B('Easy sample', 'Muestra fácil'), B('No blood needed', 'Sin necesidad de sangre'), B('The cells that come off the inside of the cheek carry the same DNA as the rest of the body.', 'Las células que se desprenden del interior de la mejilla llevan el mismo ADN que el resto del cuerpo.'))],
    [('swab', B('Rub a swab inside the cat\'s cheek', 'Frotar un bastoncillo en el interior de la mejilla del gato'), B('Some cells stay on the swab.', 'Algunas células se quedan en el bastoncillo.'), NOTHING),
     ('extract', B('Extract the DNA from the cells', 'Extraer el ADN de las células'), B('The cells are opened and the DNA is cleaned.', 'Se abren las células y se limpia el ADN.'), B('There must be cells on the swab first.', 'Tiene que haber primero células en el bastoncillo.')),
     ('pcr', B('Copy the stretch of the gene with PCR', 'Copiar el tramo del gen con PCR'), B('Millions of copies of just the stretch to test.', 'Millones de copias de solo el tramo que se quiere comprobar.'), B('The DNA has to be extracted first.', 'El ADN tiene que estar extraído antes.')),
     ('cut', B('Cut the copies with the restriction enzyme', 'Cortar las copias con la enzima de restricción'), B('Copies of one allele are cut; copies of the other are not.', 'Las copias de un alelo se cortan; las del otro no.'), B('The copies have to exist first.', 'Las copias tienen que existir antes.')),
     ('gel', B('Run the pieces on a gel', 'Hacer correr los trozos en un gel'), B('The pieces separate by size.', 'Los trozos se separan por tamaño.'), B('The copies have to be cut before they are separated.', 'Las copias tienen que estar cortadas antes de separarse.')),
     ('bands', B('Read the bands: one long band or two short ones', 'Leer las bandas: una larga o dos cortas'), B('One band means uncut copies; two short bands mean cut copies; all three together mean one of each.', 'Una banda significa copias sin cortar; dos bandas cortas, copias cortadas; las tres juntas, una de cada.'), B('The gel has to be run first.', 'El gel tiene que haberse corrido antes.')),
     ('genotype', B('Work out the genotype from the pattern of bands', 'Deducir el genotipo por el patrón de bandas'), B('The pattern shows which two alleles the cat has.', 'El patrón indica qué dos alelos tiene el gato.'), B('The bands have to be read first.', 'Las bandas tienen que haberse leído antes.')),
     ('report', B('Tell the owner what the cat carries', 'Decir al dueño lo que lleva el gato'), B('A carrier can pass the allele on to its kittens.', 'Un portador puede pasar el alelo a sus gatitos.'), B('You need the genotype first.', 'Primero necesitas el genotipo.'))],
    B('Genotype', 'Genotipo'),
    [B('The test goes from cells to DNA, to copies, to cuts, to a gel and, last, to a conclusion.', 'La prueba va de células a ADN, a copias, a cortes, a un gel y, al final, a una conclusión.'),
     B('Swab, extract, copy, cut, run the gel, read the bands, work out the genotype and report.', 'Frotis, extraer, copiar, cortar, hacer correr el gel, leer las bandas, deducir el genotipo e informar.'),
     B('Swab → extract → PCR → cut → gel → bands → genotype → report.', 'Frotis → extraer → PCR → cortar → gel → bandas → genotipo → informar.')],
    **closing(B('A genotype from a swab', 'Un genotipo a partir de un frotis'),
              B('You combined PCR, restriction enzymes and a gel, three techniques of this game, in one test that works in real laboratories.', 'Has combinado la PCR, las enzimas de restricción y un gel, tres técnicas de este juego, en una prueba que funciona en laboratorios reales.'),
              B('Tests like this are used to check pets, farm animals and crops for known alleles, and to avoid matings that would produce affected offspring.', 'Pruebas como esta se usan para comprobar mascotas, animales de granja y cultivos en busca de alelos conocidos, y para evitar cruces que darían crías afectadas.'),
              B('The method of cutting copies of a gene with a restriction enzyme and reading the gel, known as PCR-RFLP, has been used for decades to genotype single-letter changes.', 'El método de cortar copias de un gen con una enzima de restricción y leer el gel, conocido como PCR-RFLP, se usa desde hace décadas para genotipar cambios de una sola letra.'),
              B('The enzyme only cuts if its site is intact. If the changed letter breaks the site, the copy is not cut and shows one long band; if it keeps the site, it shows two short ones.', 'La enzima solo corta si su sitio está intacto. Si la letra cambiada rompe el sitio, la copia no se corta y muestra una banda larga; si lo conserva, muestra dos cortas.'),
              [B('Many commercial tests now read the letters directly instead of cutting; the steps shown here are the classic version.', 'Muchas pruebas comerciales leen ahora las letras directamente en lugar de cortar; los pasos de aquí son la versión clásica.')],
              []))

write_levels([inh_palomino, inh_rabbit, pair_insulin, seq_swab])
